pub type OwnedPtr = {
  ptr: *Int;
}
  invariant: self.ptr != null;

impl OwnedPtr {
  fn new(value: Int) -> OwnedPtr
    ensures: result.ptr != null;
  {
    let p = alloc_int(value);
    return OwnedPtr{ ptr: p };
  }

  fn get(self: &Self) -> Int
    ensures: result == self.ptr;
  {
    return self.ptr;
  }

  fn set(self: &mut Self, value: Int) {
    self.ptr = value;
  }
}

fn alloc_int(value: Int) -> *Int {
  let p = raw_alloc(8);  // Simplified
  p = value;
  return p;
}

fn main() -> Int {
  let op = OwnedPtr::new(42);
  return op.get();
}
